public void start(UPoint handlerBase, Unit controlled) {
    float angle = (float) MathUtils.getAngle(controlled.getBasePoint().x, controlled.getBasePoint().y, handlerBase.x, handlerBase.y);
    UEdge next = controlled.getEdges().iterator().next();
    this.mConstAngleDiff = ((float) MathUtils.getAngle(next.mStart.x, next.mStart.y, next.mEnd.x, next.mEnd.y)) - angle;
}
